<template><view class="page"><view class="nav"><text @click="back">‹</text><text>审计日志</text><text @click="load">⟳</text></view><scroll-view scroll-y class="list"><view v-if="loading" class="hint">加载中...</view><view v-for="l in logs" :key="l.id" class="card"><view class="row"><text class="act">{{ l.action }}</text><text>{{ l.result }}</text></view><text class="meta">{{ l.username }} · {{ l.ip }} · {{ l.createdAt }}</text><text class="target">{{ l.target }}</text></view><view v-if="!loading&&!logs.length" class="hint">暂无日志</view></scroll-view></view></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { getLogs } from '@/api/audit';const logs=ref<any[]>([]),loading=ref(false);async function load(){loading.value=true;try{const r:any=await getLogs({page:1,size:50});logs.value=Array.isArray(r)?r:(r?.records||[])}catch(e:any){uni.showToast({title:e?.message||'加载失败',icon:'none'})}finally{loading.value=false}}function back(){uni.navigateBack({fail:()=>uni.switchTab({url:'/pages/profile/index'})})}onMounted(load)</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f5f7}.nav{height:88rpx;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24rpx;font-size:32rpx;font-weight:700}.nav text:first-child{font-size:48rpx;color:#6b7280}.nav text:last-child{font-size:34rpx;color:#4f46e5}.list{height:calc(100vh - 88rpx);padding:24rpx}.hint{text-align:center;color:#9ca3af;padding:40rpx}.card{background:#fff;border-radius:20rpx;padding:24rpx;margin-bottom:16rpx}.row{display:flex;justify-content:space-between}.act{font-weight:700;color:#111827}.meta,.target{display:block;color:#6b7280;font-size:22rpx;margin-top:8rpx}</style>
